  ["scoped-source-lines", "git_status=$(\"$HORIZON_GIT\" status --porcelain=v1 --untracked-files=all); printf '%s\\n' \"$git_status\" | awk 'substr($0,4) ~ /^MainProjects\\/(Algebraic-Jacobian-Challenge-Rebuild|Algebraic-Jacobian-Challenge)\\// && substr($0,4) !~ /\\/hgraph\\// {print}'"],
  ["scoped-hgraph-summary", "git_status=$(\"$HORIZON_GIT\" status --porcelain=v1 --untracked-files=all); printf '%s\\n' \"$git_status\" | awk 'substr($0,4) ~ /^MainProjects\\/(Algebraic-Jacobian-Challenge-Rebuild|Algebraic-Jacobian-Challenge)\\/hgraph\\// {x=substr($0,1,2); if(x==\"??\")u++; else if(substr(x,1,1)!=\" \" || substr(x,2,1)!=\" \")m++; else clean++} END{printf \"scoped hgraph modified=%d untracked=%d clean-status-lines=%d\\n\",m,u,clean}'"],
  ["shared-classification", "git_status=$(\"$HORIZON_GIT\" status --porcelain=v1 --untracked-files=all); printf '%s\\n' \"$git_status\" | awk 'BEGIN{n=0;tracked=0;untracked=0;inbox=0;hgraph=0;refs=0;runs=0;search=0;other=0} {p=substr($0,4);x=substr($0,1,2); if(p ~ /^MainProjects\\/(Algebraic-Jacobian-Challenge-Rebuild|Algebraic-Jacobian-Challenge)\\//)next;n++; if(x==\"??\")untracked++; else tracked++; if(p ~ /^\\.archon-horizon\\/inbox\\//)inbox++; else if(p ~ /\\/hgraph\\// || p ~ /^\\.archon-horizon\\/hgraph\\//)hgraph++; else if(p ~ /^references\\//)refs++; else if(p ~ /^\\.archon-horizon\\/runs\\//)runs++; else if(p ~ /^\\.archon-horizon\\/search\\//)search++; else other++} END{printf \"shared total=%d tracked=%d untracked=%d inbox=%d hgraph=%d refs=%d runs=%d search=%d other=%d\\n\",n,tracked,untracked,inbox,hgraph,refs,runs,search,other}'"],
  ["staged-count", "\"$HORIZON_GIT\" diff --cached --name-only | awk 'END{print NR+0}'"],
  ["source-diff-check", "for p in MainProjects/Algebraic-Jacobian-Challenge-Rebuild MainProjects/Algebraic-Jacobian-Challenge; do printf '%s: ' \"$p\"; \"$HORIZON_GIT\" diff --quiet -- \"$p\" -- ':!*/hgraph/*' && echo clean || echo modified; done"],
  ["head-project-files", "\"$HORIZON_GIT\" ls-tree -r --name-only HEAD -- MainProjects/Algebraic-Jacobian-Challenge-Rebuild MainProjects/Algebraic-Jacobian-Challenge | awk '$0 !~ /\\/hgraph\\// && ($0 ~ /\\.lean$/ || $0 ~ /\\.tex$/ || $0 ~ /README|roadmap|Challenge\\.lean$/)' | tail -40"],
  ["hgraph-stats", "\"$HORIZON_BIN\" graph -p Algebraic-Jacobian-Challenge-Rebuild stats --json | jq '{project,states,totals,warning_count:(.warnings|length)}'"],
  ["task-list-focus", "\"$HORIZON_BIN\" task list --json | jq '[.tasks[] | select(.id==\"ajcr-reviewer-full\" or (.roadmap_refs|index(\"AJCR.review-plan\"))) | {id,status,title,roadmap_refs}]'"],
  ["inbox-attention", "\"$HORIZON_BIN\" inbox list --json | jq '{attention,warnings,counts:(.items|group_by(.kind)|map({kind:.[0].kind,count:length}))}'"]
];
const rs = await Promise.all(cmds.map(async ([name,cmd]) => {
  const r=await tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:8000});
  return `---${name}---\n${r.output}`;
}));
rs.forEach(text);

